//! Parity between [`EnglishTagger`] and spaCy 3.8's `en_core_web_sm` 3.8.0
//! `tok2vec` + `tagger`, loaded as misaki loads them.
//!
//! The fixture (`tests/fixtures/spacy_tagger_oracle.json`) is checked in and
//! was generated by
//! `crates/boostr-audio/tests/tools/kokoro_g2p_oracle/spacy_tagger_oracle.py`.
//! It covers the 388-sentence narration corpus and the tokenizer stress set.
//!
//! `tags_match_spacy` tokenizes each text with [`SpacyTokenizer`] and
//! asserts every token's text and `tag_`. `tok2vec_matches_spacy` asserts
//! the `tok2vec` output of the sentences that carry it within 1e-5. All
//! mismatches print before a test fails.

use boostr_audio::g2p::spacy_tagger::EnglishTagger;
use boostr_audio::g2p::spacy_tokenizer::SpacyTokenizer;
use serde::Deserialize;

mod common;
use common::load_json;

/// Largest absolute `tok2vec` difference accepted.
const TOK2VEC_TOLERANCE: f32 = 1e-5;

#[derive(Debug, Deserialize)]
struct Fixture {
    source: String,
    width: usize,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    set: String,
    text: String,
    /// `[text, tag]`.
    tokens: Vec<(String, String)>,
    tok2vec: Option<Vec<f32>>,
}

fn fixture() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/spacy_tagger_oracle.json"
    );
    let fixture: Fixture = load_json(std::path::Path::new(path));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    fixture
}

fn pipeline(fixture: &Fixture) -> (SpacyTokenizer, EnglishTagger) {
    let tokenizer =
        SpacyTokenizer::en_core_web_sm().unwrap_or_else(|e| panic!("SpacyTokenizer: {e}"));
    let tagger = EnglishTagger::new().unwrap_or_else(|e| panic!("EnglishTagger: {e}"));
    assert_eq!(
        tagger.source(),
        fixture.source,
        "the fixture and the embedded weights come from different spaCy builds"
    );
    assert_eq!(tagger.width(), fixture.width);
    (tokenizer, tagger)
}

#[test]
fn tags_match_spacy() {
    let fixture = fixture();
    let (tokenizer, tagger) = pipeline(&fixture);

    let mut failures = Vec::new();
    let mut exact = std::collections::BTreeMap::<&str, (usize, usize, usize, usize)>::new();
    for case in &fixture.cases {
        let tokens = tokenizer.tokenize(&case.text);
        let tags = tagger
            .tag(&tokens)
            .unwrap_or_else(|e| panic!("tag({:?}): {e}", case.text));
        let got: Vec<(String, String)> = tokens.iter().map(|t| t.text.clone()).zip(tags).collect();
        let entry = exact.entry(case.set.as_str()).or_default();
        entry.1 += 1;
        entry.3 += case.tokens.len();
        entry.2 += got.iter().zip(&case.tokens).filter(|(g, w)| g == w).count();
        if got == case.tokens {
            entry.0 += 1;
            continue;
        }
        let mut report = format!("[{}] {:?}", case.set, case.text);
        for i in 0..got.len().max(case.tokens.len()) {
            let (g, w) = (got.get(i), case.tokens.get(i));
            if g != w {
                report.push_str(&format!("\n  token {i}: rust {g:?}, spacy {w:?}"));
            }
        }
        failures.push(report);
    }
    for (set, (ok, total, tok_ok, tok_total)) in &exact {
        println!("{set}: {ok}/{total} texts exact, {tok_ok}/{tok_total} tokens exact");
    }
    for f in &failures {
        println!("{f}");
    }
    assert!(
        failures.is_empty(),
        "{} of {} texts mismatched; see the output above",
        failures.len(),
        fixture.cases.len()
    );
}

#[test]
fn tok2vec_matches_spacy() {
    let fixture = fixture();
    let (tokenizer, tagger) = pipeline(&fixture);

    let mut checked = 0usize;
    let mut failures = Vec::new();
    for case in &fixture.cases {
        let Some(want) = &case.tok2vec else {
            continue;
        };
        checked += 1;
        let tokens = tokenizer.tokenize(&case.text);
        let got = tagger
            .tok2vec(&tokens)
            .unwrap_or_else(|e| panic!("tok2vec({:?}): {e}", case.text));
        if got.len() != want.len() {
            failures.push(format!(
                "{:?}: {} values, spaCy has {}",
                case.text,
                got.len(),
                want.len()
            ));
            continue;
        }
        let (worst, at) = got
            .iter()
            .zip(want)
            .map(|(g, w)| (g - w).abs())
            .enumerate()
            .fold(
                (0f32, 0usize),
                |acc, (i, d)| if d > acc.0 { (d, i) } else { acc },
            );
        println!("{:?}: max |diff| {worst:e}", case.text);
        if worst > TOK2VEC_TOLERANCE {
            failures.push(format!(
                "{:?}: token {} dim {} differs by {worst:e}",
                case.text,
                at / fixture.width,
                at % fixture.width
            ));
        }
    }
    for f in &failures {
        println!("{f}");
    }
    assert!(checked > 0, "fixture carries no tok2vec vectors");
    assert!(
        failures.is_empty(),
        "{} of {checked} sentences exceed {TOK2VEC_TOLERANCE:e}; see the output above",
        failures.len()
    );
}
